CREATE TABLE IF NOT EXISTS job_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), sender_id uuid NOT NULL REFERENCES users(id), body text NOT NULL CHECK (length(body) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inspection_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), mechanic_id uuid NOT NULL REFERENCES users(id), category text NOT NULL CHECK (category IN ('recommended_now','plan_for_later','monitor')), note text NOT NULL, attachment_id uuid REFERENCES upload_references(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid REFERENCES jobs(id), customer_id uuid NOT NULL REFERENCES users(id), currency char(3) NOT NULL, total_minor bigint NOT NULL CHECK (total_minor >= 0), status text NOT NULL CHECK (status IN ('draft','open','paid','void','uncollectible')), due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoice_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), description text NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor >= 0), quantity numeric(12,3) NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_job_messages_job ON job_messages(job_id, created_at);
CREATE INDEX IF NOT EXISTS idx_findings_job ON inspection_findings(job_id, created_at);
CREATE INDEX IF NOT EXISTS idx_invoices_customer ON invoices(customer_id, created_at DESC);
